<template>
  <BioNexusDialog ref="box" size="standard" :kicker="mode === 'create' ? 'Nuevo registro' : 'Editar registro'" :title="mode === 'create' ? 'Crear impuesto' : 'Editar impuesto'" :prevent-close="saving || dirty" @before-close="requestClose" @close="handleClosed">
