function display(v){const digits=Number(settings.settings.monetary_decimals)||0;return Number(formatRegionalNumber(v,settings.settings,{minimumFractionDigits:digits,maximumFractionDigits:digits}).replace(/[^0-9,-.]/g,""))||Number(v)||0}function syncDirty(){dirty.value=signature.value!==original.value;if(errorMessage.value)errorMessage.value=""}function assign(row){draft.description=row?.description||"";draft.value=Number(row?.value)||0;draft.only_dollars=Boolean(row?.only_dollars);draft.always_subtotal=Boolean(row?.always_subtotal)}async function show(){await box.value?.open();await nextTick();original.value=signature.value;dirty.value=false;firstInput.value?.focus()}async function openCreate(){mode.value="create";current.value=null;assign(null);attempted.value=false;errorMessage.value="";await show()}async function openEdit(row){mode.value="edit";current.value=row;assign(row);attempted.value=false;errorMessage.value="";await show()}async function requestClose(){if(props.saving)return;if(dirty.value){const accepted=await discardDialog.value?.ask({title:"Descartar cambios",message:"Hay cambios sin guardar. ¿Deseas salir y descartarlos?",confirmText:"Sí, salir y descartar cambios",confirmIcon:"delete",variant:"danger"});if(!accepted)return}box.value?.close()}function close(){box.value?.close()}function handleClosed(){attempted.value=false;errorMessage.value="";dirty.value=false}function setError(v){errorMessage.value=String(v||"")}function clearError(){errorMessage.value=""}function markSaved(row){current.value=row;assign(row);original.value=signature.value;dirty.value=false;attempted.value=false;errorMessage.value=""}function submit(){attempted.value=true;if(descriptionError.value||valueError.value||submitDisabled.value)return;emit("submit",{mode:mode.value,record:current.value,values:values.value})}defineExpose({openCreate,openEdit,close,requestClose,setError,clearError,markSaved});
