<style scoped>.tax-dialog-body{display:grid;gap:var(--bio-nexus-space-3)}.tax-form-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(150px,1fr);gap:var(--bio-nexus-space-3);align-items:start}.tax-options{grid-column:1/-1;display:flex;gap:var(--bio-nexus-space-4);flex-wrap:wrap}@media(max-width:620px){.tax-form-grid{grid-template-columns:1fr}}</style>
